#!/usr/bin/env bash
set -euo pipefail
rm -rf .backend /tmp/backend.tar.gz
mkdir -p .backend
cat > /tmp/backend.tar.gz.b64 <<'B64'

B64
base64 -d /tmp/backend.tar.gz.b64 > /tmp/backend.tar.gz
tar -xzf /tmp/backend.tar.gz -C .backend --strip-components=1
MODFILE=$(find .backend -type f -name go.mod -print -quit)
if [ -z "$MODFILE" ]; then
  echo "ERROR: go.mod not found after extracting backend"
  find .backend -maxdepth 3 -type f | head -100
  exit 1
fi
MODDIR=$(dirname "$MODFILE")
echo "Building Go module from: $MODDIR"
cd "$MODDIR"
go mod tidy
go build -tags netgo -ldflags '-s -w' -o "$OLDPWD/app"
